using Godot;

/// <summary>
/// The music: one track at a time, crossfaded when it changes. A child of <see cref="GameRoot"/>
/// so it carries on across screens - the menu track plays unbroken from the title through
/// fighter and stage select, and only a match changes it.
///
/// The tracks are generated by tools/audio/music.py and loop seamlessly by construction. The
/// victory sting is the one that does not loop; it is played with <see cref="PlayOnce"/>.
/// </summary>
public partial class MusicPlayer : Node
{
	public const string Menu = "menu";
	public const string Battle = "battle";
	/// <summary>Under the talking in story scenes - quiet in the range the talking blips use.</summary>
	public const string Story = "story";
	/// <summary>DoomBot's boss theme. Opens on bare fifths, so FIGHT!'s A major chord sits on it.</summary>
	public const string Boss = "doombot";
	/// <summary>A three-second sting for a story fight won. Play it with <see cref="PlayOnce"/>.</summary>
	public const string Victory = "victory";

	public static MusicPlayer Instance { get; private set; }

	/// <summary>Where the music sits under the sound effects. Every track is mastered to the same
	/// peak, so this one number is the whole music-to-effects balance.</summary>
	const float VolumeDb = -9.0f;

	/// <summary>How far the music drops while the game is paused - still there, clearly waiting.</summary>
	const float PausedDb = -12.0f;

	const float FadeSeconds = 0.6f;

	AudioStreamPlayer current;
	AudioStreamPlayer fading;
	string currentName = "";
	bool currentOnce;
	float duckDb;

	/// <summary>A track asked for while a sting was still sounding: it comes in when the sting ends.
	/// A story's scene after a win asks for its music on its first line, and the sting is the point.</summary>
	string afterSting;

	public override void _Ready()
	{
		Instance = this;
		ProcessMode = ProcessModeEnum.Always;
		current = MakePlayer();
		fading = MakePlayer();
	}

	public override void _ExitTree()
	{
		if (Instance == this) Instance = null;
	}

	AudioStreamPlayer MakePlayer()
	{
		var player = new AudioStreamPlayer { Bus = SfxPlayer.MusicBus, VolumeDb = -80.0f };
		AddChild(player);
		return player;
	}

	/// <summary>Plays a track, crossfading from whatever was playing. Asking for the track that is
	/// already playing does nothing, so screens can ask freely.</summary>
	public static void Play(string name) => Instance?.Switch(name, once: false);

	/// <summary>
	/// Plays a track once, then leaves silence - for a sting. Whatever was playing fades out under
	/// it as <see cref="Play"/> would fade it, but the sting itself starts at full level: its first
	/// note is the point of it, and faded in it would land late. Only a file built without a loop
	/// plays once; music.py marks which are which.
	/// </summary>
	public static void PlayOnce(string name) => Instance?.Switch(name, once: true);

	/// <summary>Fades the music out.</summary>
	public static void Stop() => Instance?.Switch("", once: false);

	/// <summary>
	/// Speeds the current track up - DoomBot's theme on his last stock. The pitch rises with it,
	/// which a cartoon gets away with and a real band could not. Changing track puts the speed
	/// back to normal, so a sped-up theme can never leak into the next screen.
	/// </summary>
	public static void SetSpeed(float speed)
	{
		if (Instance != null) Instance.current.PitchScale = speed;
	}

	/// <summary>Turns the music down while paused, and back up after.</summary>
	public static void SetPaused(bool paused)
	{
		if (Instance != null) Instance.duckDb = paused ? PausedDb : 0.0f;
	}

	void Switch(string name, bool once)
	{
		if (!once && currentOnce && currentName != "" && current.Playing)
		{
			afterSting = name;
			return;
		}
		afterSting = null;
		if (name == currentName) return;
		currentName = name;
		currentOnce = once;

		(current, fading) = (fading, current);
		current.Stop();
		current.VolumeDb = -80.0f;
		current.PitchScale = 1.0f;
		if (name == "") return;

		AudioStream stream = SfxPlayer.Load($"res://assets/music/{name}.wav", loops: !once);
		if (stream == null) return;
		current.Stream = stream;
		if (once) current.VolumeDb = VolumeDb + duckDb;
		current.Play();
	}

	public override void _Process(double delta)
	{
		// A sting that has finished leaves silence, and forgets its name so it can play again.
		if (currentOnce && currentName != "" && !current.Playing)
		{
			currentName = "";
			if (afterSting != null) Switch(afterSting, once: false);
		}

		// Fades in decibels feel uneven - most of the change happens at the quiet end - so fade
		// the linear gain and convert.
		float step = (float)delta / FadeSeconds;
		float target = Mathf.DbToLinear(VolumeDb + duckDb);
		float now = Mathf.DbToLinear(current.VolumeDb);
		current.VolumeDb = Mathf.LinearToDb(Mathf.MoveToward(now, currentName == "" ? 0.0f : target, step * target));

		if (fading.Playing)
		{
			float old = Mathf.MoveToward(Mathf.DbToLinear(fading.VolumeDb), 0.0f, step * target);
			fading.VolumeDb = Mathf.LinearToDb(old);
			if (old <= 0.0001f) fading.Stop();
		}
	}
}
